import{z as l,x as i,o as s,c as d,q as t,j as B,D as r,d as a,s as o,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"调度器的架构","description":"","frontmatter":{"title":"调度器的架构","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/orch-scheduler-arch.md","filePath":"cs/orch-scheduler-arch.md","lastUpdated":1791413859000}'),p={name:"cs/orch-scheduler-arch.md"};function u(m,E,c,h,C,g){const A=i("Mermaid");return s(),d("div",null,[E[2]||(E[2]=t('<h1 id="调度器的架构" tabindex="-1">调度器的架构 <a class="header-anchor" href="#调度器的架构" aria-label="Permalink to &quot;调度器的架构&quot;">​</a></h1><div class="epigraph"><p>调度器的输入不是集群的真相，是一份刚要过期的快照；它的每个决定，都在赌「读到的账」与「真实的账」之间的差值足够小。</p><footer>—— 据 Verma et al., Large-scale cluster management at Google with Borg, EuroSys 2015 与 Kubernetes 调度文档整理</footer></div><p><a href="/cs/npk-map">上一课</a>给「网络协议栈实践」收束：正向是包的旅程，逆向是排障的判定序，四条骨架跨版本成立——状态有地址、转移有动作、排队有预算、拒绝有计数。协议栈的图拼完，本课程到此接棒：单机上「怎么隔离」已有答案，编排要回答的是几千台宿主、几十万个容器时<strong>放哪、怎么收敛、怎么记账</strong>。本课是「容器编排」第一课，从「谁决定落点」开始。主干课 <a href="/cs/borg-kubernetes">Borg 与 Kubernetes</a> 给过控制面形状——强一致的小状态加最终一致的调和，还钉过绑定要带资源版本防双绑；本课拆调度器内部：队列、过滤、打分、绑定。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>集群里有两种持续变化的量：一列待安排的意图（新 pod 要 CPU、内存、拓扑位置），一张资源地图（每台节点还剩什么）。缺口不是「找一台装得下的机器」——单次匹配谁都会写，难的是高频决定下账本不重不漏：同一份资源被记到两台节点上，或者明明有节点装得下却没人被选中。Borg 的论文给了规模参照：中等规模的 cell 每分钟安排上万个任务。快与不重账，本课要拆调度器怎么同时拿到这两样。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是流水线加缓存。调度器不逐次读存储，而是 watch 全量对象进本地缓存（informer）——它读的是快照，不是真相，这笔账下文算。新 pod 进调度队列，按优先级与退避排序；一个调度周期四步：<strong>过滤</strong>把不满足硬约束（request 装不下、端口冲突、卷拓扑）的节点剔掉，剩下可行集；<strong>打分</strong>在可行集上按加权策略求和，取最高分；<strong>假设</strong>（assume）——先在自己的缓存里把这份资源预记上；<strong>绑定</strong>——写 binding 对象回 API，kubelet 看到绑定才真正起容器。</p><p><span class="marginnote">术语翻译：informer 缓存就是调度器自带的「复印本」——watch 把每一次变化推过来、随时更新本地副本，查账只翻复印本、不去档案室（API 存储）排队；代价是复印与盖章之间有时间差，所以调度器读到的永远是刚要过期的快照。</span></p>',8)),(s(),B(n,null,{default:r(()=>[o(A,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20POD%5B%22%E6%96%B0%20pod%20%E5%85%A5%E9%98%9F%22%5D%20--%3E%20CACHE%5B%22%E8%AF%BB%E6%9C%AC%E5%9C%B0%E7%BC%93%E5%AD%98%E5%BF%AB%E7%85%A7%22%5D%0A%20%20CACHE%20--%3E%20FIL%5B%22%E8%BF%87%E6%BB%A4%3A%20%E5%8F%AF%E8%A1%8C%E8%8A%82%E7%82%B9%E9%9B%86%22%5D%0A%20%20FIL%20--%3E%20SC%5B%22%E6%89%93%E5%88%86%3A%20%E5%8A%A0%E6%9D%83%E6%B1%82%E5%92%8C%22%5D%0A%20%20SC%20--%3E%20ASM%5B%22assume%3A%20%E7%BC%93%E5%AD%98%E5%86%85%E9%A2%84%E8%AE%B0%E8%B4%A6%22%5D%0A%20%20ASM%20--%3E%20BIND%5B%22binding%20%E5%86%99%E5%9B%9E%20API%22%5D%0A%20%20BIND%20--%3E%20OK%7B%22%E5%AF%B9%E8%B1%A1%E7%89%88%E6%9C%AC%E5%86%B2%E7%AA%81%3F%22%7D%0A%20%20OK%20--%3E%7C%22%E6%98%AF%22%7C%20RE%5B%22%E9%87%8D%E6%96%B0%E5%85%A5%E9%98%9F%E9%87%8D%E7%AE%97%22%5D%0A%20%20OK%20--%3E%7C%22%E5%90%A6%22%7C%20KL%5B%22kubelet%20%E6%8E%A5%E6%89%8B%E8%BF%90%E8%A1%8C%22%5D%0A"})]),fallback:r(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("快照过期靠"),e("strong",null,"假设"),a("兜底：assume 使同一时刻一个 pod 只在一个周期里被处理，后续 pod 读到的缓存已扣掉这份资源——调度器内部的重账被串行化消灭。调度器与世界之间的竞争（别的组件恰好把节点占满）交给绑定写回时的乐观并发：对象版本对不上就失败重入队。不这么做会错在哪：没有预记账，高峰期两个周期读到同一张地图，同一台节点被超卖；没有写回校验，过时快照的决定会静默覆盖真相。")],-1)),E[5]||(E[5]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：assume 像服务员下单后先在墙上小黑板划掉一道菜——别的服务员看一眼黑板就知道没了，不必等厨房盘点确认；小黑板（缓存）与后厨库存（真实状态）偶尔对不上，就靠出单时核对订单号（写回校验）兜底，对不上就退单重下。")],-1)),E[6]||(E[6]=e("p",null,"硬约束与软偏好的分工是结构性的：过滤收缩可行域，打分在剩下的里面挑。把软偏好写成硬约束，可行集会空洞化（找不到任何节点）；把硬约束写成打分项，「必须满足」退化成「倾向满足」。谱系上还有两条路：Mesos 把调度拆成两级，框架拿资源要约自己排，框架自由但全局视图碎掉；Omega 让所有调度器共享状态、乐观并发，并发高但冲突重算贵。Kubernetes 选集中式悲观：冲突率低时它最便宜。Burns 等人在 CACM 2016 对照三代后的结论正是：选择取决于冲突率与视图新鲜度的权衡，不存在全赢的架构。",-1)),(s(),B(n,null,{default:r(()=>[o(A,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20JOB%5B%22%E4%B8%80%E6%89%B9%E5%BE%85%E8%B0%83%E5%BA%A6%E7%9A%84%E4%BB%BB%E5%8A%A1%22%5D%20--%3E%20M%5B%22Mesos%3A%20%E4%B8%A4%E7%BA%A7%E8%A6%81%E7%BA%A6%22%5D%0A%20%20M%20--%3E%20M2%5B%22%E6%A1%86%E6%9E%B6%E6%8B%BF%E5%88%B0%E8%B5%84%E6%BA%90%E9%82%80%E7%BA%A6%E8%87%AA%E5%B7%B1%E6%8E%92%22%5D%0A%20%20M2%20--%3E%20M3%5B%22%E6%A1%86%E6%9E%B6%E8%87%AA%E7%94%B1%2C%20%E5%85%A8%E5%B1%80%E8%A7%86%E5%9B%BE%E7%A2%8E%22%5D%0A%20%20JOB%20--%3E%20O%5B%22Omega%3A%20%E5%85%B1%E4%BA%AB%E7%8A%B6%E6%80%81%E4%B9%90%E8%A7%82%E5%B9%B6%E5%8F%91%22%5D%0A%20%20O%20--%3E%20O2%5B%22%E5%A4%9A%E8%B0%83%E5%BA%A6%E5%99%A8%E5%B9%B6%E5%8F%91%E9%AB%98%2C%20%E5%86%B2%E7%AA%81%E6%97%B6%E9%87%8D%E7%AE%97%E8%B4%B5%22%5D%0A%20%20JOB%20--%3E%20K%5B%22Kubernetes%3A%20%E9%9B%86%E4%B8%AD%E5%BC%8F%E5%8D%95%E8%B0%83%E5%BA%A6%E5%99%A8%22%5D%0A%20%20K%20--%3E%20K2%5B%22assume%20%E4%B8%B2%E8%A1%8C%E5%8C%96%E5%8A%A0%E5%86%99%E5%9B%9E%E6%A0%A1%E9%AA%8C%2C%20%E5%86%B2%E7%AA%81%E7%8E%87%E4%BD%8E%E6%97%B6%E6%9C%80%E4%BE%BF%E5%AE%9C%22%5D%0A"})]),fallback:r(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=t('<p><span class="marginnote">常见误区：初学者容易把「想让它优先去大节点」这类偏好写成硬约束（如 nodeSelector）。硬约束是门槛——不满足直接剔除，一旦可行集空了 pod 就永远 Pending；偏好应放进打分项，让它只是「倾向」而不是「资格」。</span></p><p><span class="marginnote">打分权重是策略不是常数：默认把「资源配比均衡」与「低占用优先」两项加权求和；权重调偏会系统性制造碎片——大作业进不来，小作业填一地。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写一组任务绑在一起调度的 gang 调度，不写 GPU 拓扑对齐，也不写节点集合本身伸缩时的行为。调度决定是<strong>一次性的</strong>：pod 绑定后不搬家，哪怕更合适的节点后来空出来；重排是另外的工具，不在调度循环里。快照过期的残余风险由调和兜底：绑错顶多不优，不会错账——记账的真相在 API 对象里，快照只是输入。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>结构是缓存快照 + 队列 + 过滤 + 打分 + 假设 + 绑定；快与不重账同时成立。</li><li>assume 串行化调度器内部，乐观并发兜住调度器与世界之间；冲突重算即可。</li><li>硬约束收缩可行集、软偏好加权打分，二者不能互相冒充。</li><li>Mesos 两级、Omega 共享、Kubernetes 集中悲观，按冲突率选择，没有全赢架构。</li><li>出处：Verma et al., EuroSys 2015；Burns et al., CACM 2016；Kubernetes 官方调度文档。</li></ul>',6))])}const f=l(p,[["render",u]]);export{b as __pageData,f as default};
